// Round 2 (owner decision 11, ENG-4; Claude, lane B, 31 October 2026): frozen report documents are read with the
// validator of the profile they were written with, never with live wording, the live catalog or the live results decoder.
// The committed golden v1 version (generated by the I-10 code at master 796bece, never regenerated) must keep opening, and
// must serve as the previous approved version of a new (v2) version's change log, whatever later code changes.
import { describe, expect, test } from 'bun:test'
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { SCOPE3_METHODS } from './scope3-method-catalog'
import {
  buildScope3ReportDocument, scope3ReportApprovalLines, scope3ReportCsv, scope3ReportExportCsv, scope3ReportText, SCOPE3_REPORT_PROFILE, SCOPE3_REPORT_PROFILE_V1, SCOPE3_REPORT_PROFILE_V2, SCOPE3_REPORT_PROFILE_V3,
  validateScope3ReportDocument, validateScope3ReportVersionSummary, type Scope3ReportVersionSummary,
} from './scope3-report-document'
import { validateScope3ReportDocumentV1 } from './scope3-report-v1'
import { validateScope3ReportDocumentV2 } from './scope3-report-v2'
import type { Scope3ResultsDocument } from './scope3-trace'

const sha256 = (text: string | Buffer) => createHash('sha256').update(text).digest('hex')
const file = (name: string) => readFileSync(new URL(name, import.meta.url))
const golden = JSON.parse(file('./testdata/scope3-report-v1-golden.json').toString('utf8')) as { summary: Record<string, any>; reportText: string; csvText: string }
const goldenV2 = JSON.parse(file('./testdata/scope3-report-v2-golden.json').toString('utf8')) as { companyId: string; reportText: string; csvText: string; reportSha256: string; csvSha256: string }
const fixture: Scope3ResultsDocument = JSON.parse(readFileSync(new URL('../../../apps/site-web/src/lib/scope3-results.fixture.json', import.meta.url), 'utf8'))
const company = golden.summary.companyId as string
const labels = { kind: (kind: string) => `kind ${kind}`, reason: (code: string) => `reason ${code}`, period: (start: string | null | undefined, end: string | null | undefined) => `${start} to ${end}` }
/** The golden's summary as the API lists it since round 2 (the 0030 columns it adds; v1 versions have no open-issue list). */
const goldenSummary = { ...golden.summary, openIssues: [], approval: { ...golden.summary.approval, acknowledgedOpenIssues: null, selfApprovalConfirmed: false } } as unknown as Scope3ReportVersionSummary

describe('frozen Scope 3 report documents (round 2, owner decision 11)', () => {
  test('the frozen validators and the golden v1 version never change (their bytes are pinned)', () => {
    // Pins of the files that must never change once a document of their profile may exist. Edit neither: add a v3 validator.
    expect(sha256(file('./scope3-report-v1.ts'))).toBe(FROZEN.v1)
    expect(sha256(file('./scope3-report-v2.ts'))).toBe(FROZEN.v2)
    expect(sha256(file('./testdata/scope3-report-v1-golden.json'))).toBe(FROZEN.golden)
    expect(SCOPE3_REPORT_PROFILE).toBe(SCOPE3_REPORT_PROFILE_V3)
    expect(sha256(file('./testdata/scope3-report-v2-golden.json'))).toBe('afe721888ac7f8b5ec5bcec0096756045bc3825cf03697be7bc2f9a88398ad0f')
  })

  test('the golden v1 version opens: its bytes hash to its summary, its document validates with the v1 rules', () => {
    expect(sha256(golden.reportText)).toBe(golden.summary.reportSha256)
    expect(sha256(golden.csvText)).toBe(golden.summary.csvSha256)
    const document = validateScope3ReportDocument(JSON.parse(golden.reportText), company)
    expect(document.profile).toBe(SCOPE3_REPORT_PROFILE_V1)
    expect(validateScope3ReportDocumentV1(JSON.parse(golden.reportText), company).revision).toBe(1)
    expect(validateScope3ReportVersionSummary(goldenSummary, company).reportSha256).toBe(golden.summary.reportSha256)
    // It is not a v2 document, and the v2 rules refuse it.
    expect(() => validateScope3ReportDocumentV2(JSON.parse(golden.reportText), company)).toThrow()
  })

  test('a stored version never depends on live wording or the live catalog: a catalog title change leaves v1 and v2 readable', () => {
    const v2 = goldenV2.reportText
    const method = SCOPE3_METHODS['scope3.cat1_2.spend_based.epa_sc_v1_3.v1'] as unknown as { title: string } | undefined
    const any = method ?? (Object.values(SCOPE3_METHODS)[0] as unknown as { title: string })
    const title = any.title
    try {
      any.title = 'A later, corrected method title'
      expect(validateScope3ReportDocument(JSON.parse(golden.reportText), company).profile).toBe(SCOPE3_REPORT_PROFILE_V1)
      expect(validateScope3ReportDocument(JSON.parse(v2), fixture.companyId).profile).toBe(SCOPE3_REPORT_PROFILE_V2)
    } finally { any.title = title }
  })

  test('the golden v1 version is the base of a new v3 version’s change log (engine-held lines compared by engine status)', () => {
    const v1 = validateScope3ReportDocument(JSON.parse(golden.reportText), company)
    const next = buildScope3ReportDocument({ results: fixture, reportingYear: 2025, revision: 2, setupVersionId: '93100000-0000-4000-8000-0000000000c1', consolidationApproach: 'operational_control',
      preparedBy: '93100000-0000-4000-8000-0000000000a1', preparedAt: '2026-10-31T10:00:00.000Z', previous: { summary: goldenSummary, document: v1 } })
    expect(next.profile).toBe(SCOPE3_REPORT_PROFILE_V3)
    expect(next.changeLog).toMatchObject({ basis: 'previous_approved_version', previous: { versionId: golden.summary.id, revision: 1, reportSha256: golden.summary.reportSha256 } })
    // v1 listed the withdrawn trip T-2; v2 counts withdrawn records instead of listing them, so the change log names it removed.
    const t2 = v1.results.records.find(row => row.sourceId === 'T-2')!
    expect(t2.plan.status).toBe('withdrawn')
    expect(next.changeLog.records.removed).toEqual([{ recordId: t2.recordId, kind: t2.kind, category: t2.category, versionId: t2.versionId }])
    // v1 called a line the engine held `calculated`; v2 calls it `held`. With the same version and figure it is not an edit.
    // Round 2 integration: lane A's oil term (owner decision 2) moved the CAMX upstream lines (3B and 3C upstream) of the
    // electricity record after the golden was frozen at 796bece, so exactly the lines whose figure changed are edits (with
    // both figures); no engine-held line is one (the fixture has none today; the rule holds for any later fixture).
    const before = new Map(v1.results.records.map(row => [`${row.recordId}|${row.kind}`, row]))
    const moved = fixture.records.filter(row => { const old = before.get(`${row.recordId}|${row.kind}`); return !!old && old.versionId === row.versionId && !!old.result?.total && !!row.result?.total && old.result.total.display !== row.result.total.display })
    expect(moved.map(row => row.kind).sort()).toEqual(['electricity_upstream', 'td_losses_upstream'])
    expect(next.changeLog.records.edited.map(edit => [edit.kind, edit.totalBefore, edit.totalAfter]).sort())
      .toEqual(moved.map(row => [row.kind, before.get(`${row.recordId}|${row.kind}`)!.result!.total!.display, row.result!.total!.display]).sort())
    const engineHeld = new Set(fixture.records.filter(row => row.outcome === 'held' && row.result !== null).map(row => `${row.recordId}|${row.kind}`))
    expect(next.changeLog.records.edited.filter(edit => engineHeld.has(`${edit.recordId}|${edit.kind}`))).toEqual([])
    // The new version's own document and CSV are complete.
    const text = scope3ReportText(next)
    expect(validateScope3ReportDocument(JSON.parse(text), fixture.companyId).profile).toBe(SCOPE3_REPORT_PROFILE_V3)
    const csv = scope3ReportCsv(next, labels)
    expect(csv).toContain(`# Change log: compared with revision 1 (version ${golden.summary.id}, report sha256 ${golden.summary.reportSha256})`)
    expect(csv).toContain(`# Readiness when prepared: ${fixture.readiness!.openIssues.length} open issues; approval requires an explicit acknowledgement.`)
  })

  test('the exported CSV of a version is its stored bytes, then the approval: acknowledged open issues and a self-approval as a control exception', () => {
    const openIssues = fixture.readiness!.openIssues
    const approval = { approvedBy: '93100000-0000-4000-8000-0000000000a1', approvedAt: '2026-10-31T11:00:00.000Z', selfApproved: true, reportSha256: 'a'.repeat(64), acknowledgedOpenIssues: openIssues, selfApprovalConfirmed: true }
    const lines = scope3ReportApprovalLines({ approval })
    expect(lines[0]).toBe('Approval: approved by 93100000-0000-4000-8000-0000000000a1 at 2026-10-31T11:00:00.000Z.')
    expect(lines).toContain(`Approved with ${openIssues.length} open issues acknowledged by the approver (listed above).`)
    expect(lines).toContain('Open issue, category 5: Records need input.')
    expect(lines[lines.length - 1]).toBe('Control exception: self-approval. The preparer approved their own version and confirmed it explicitly; preparer and approver are not separated.')
    expect(scope3ReportApprovalLines({ approval: { ...approval, selfApproved: false, selfApprovalConfirmed: false, acknowledgedOpenIssues: null } })).toEqual([lines[0]])
    expect(scope3ReportApprovalLines({ approval: null })).toEqual(['Approval: not approved.'])
    const exported = scope3ReportExportCsv(golden.csvText, { approval })
    expect(exported.startsWith(golden.csvText)).toBe(true)
    expect(sha256(exported.slice(0, golden.csvText.length))).toBe(golden.summary.csvSha256)
    expect(exported.slice(golden.csvText.length).split('\n').filter(Boolean).every(line => line.startsWith('# ') || line.startsWith('"# '))).toBe(true)
  })
})

/** The pins (round 2, lane B). */
const FROZEN = {
  v1: 'b3a13e0c0b4c2bd56b88844791a4cabc512594036a3fc1cdf01ed5cdd625e5cb',
  v2: '111355e60c9552207ddbac95b2bb1f26c0cfcc3678c801c41598716def56be46',
  golden: 'affde19fb3cf2c7e55a0451b3885bf56f897017dd1aff865d7110c399e701cfb',
}
